import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { collationDescription } from '../src/charsets.ts'

/** Generated by scripts/gen-collation-fixtures.php from phpMyAdmin's Collation class. */
const expected = JSON.parse(
  readFileSync(new URL('./fixtures/collation-descriptions.json', import.meta.url), 'utf8'),
) as Record<string, string>

describe('Collation::buildDescription port', () => {
  it('matches phpMyAdmin for every MySQL 8.4 collation and the MariaDB/legacy extras', () => {
    const got = Object.fromEntries(Object.keys(expected).map((n) => [n, collationDescription(n)]))
    expect(got).toEqual(expected)
  })
})
